PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?kingdom
WHERE {
  {
    SELECT ?species ?kingdom
    WHERE {
      ?species a dbo:Species ;
              dbo:conservationStatus ?status ;
              dbo:kingdom ?kingdom .
      FILTER (regex(str(?status), "Endangered|Critically endangered", "i"))
    }
  }
}
GROUP BY ?kingdom
ORDER BY DESC(COUNT(DISTINCT ?species))
LIMIT 3

results.generated_sparql:
SELECT DISTINCT ?kingdom WHERE {
  ?species <http://www.w3.org/1999/02/22-rdf-syntax-ns#type> <http://dbpedia.org/ontology/Species> .
  ?species <http://dbpedia.org/property/conservationStatus> ?status .
  ?species <http://dbpedia.org/property/kingdom> ?kingdom .
  FILTER (CONTAINS(STR(?status), "Endangered"))
} GROUP BY ?kingdom ORDER BY DESC(COUNT(?species)) LIMIT 3

